<section class="hero"><div class="container"><form class="search-bar" method="get" action="<?= e(url('/')) ?>"><div class="search-field"><label for="location">Địa điểm</label><input id="location" name="location" value="<?= e($filters['location']??'') ?>" placeholder="Bạn muốn đi đâu?"></div><div class="search-field"><label for="check_in">Nhận phòng</label><input id="check_in" type="date" name="check_in" value="<?= e($filters['check_in']??'') ?>" min="<?= date('Y-m-d') ?>"></div><div class="search-field"><label for="check_out">Trả phòng</label><input id="check_out" type="date" name="check_out" value="<?= e($filters['check_out']??'') ?>" min="<?= date('Y-m-d',strtotime('+1 day')) ?>"></div><div class="search-field"><label for="guests">Số khách</label><input id="guests" type="number" min="1" name="guests" value="<?= e($filters['guests']??1) ?>"></div><button class="btn btn-primary search-button" type="submit">Tìm chỗ ở →</button></form><div class="hero-copy"><p class="eyebrow">ĐẬU ĐỖ · THƯ GIÃN · KẾT NỐI</p><h1>Tìm nơi bạn muốn đến.</h1><p>Từ căn hộ tiện nghi đến ngôi nhà bình yên — luôn có một chỗ dành cho bạn.</p></div></div></section>
