<?php if(!$listings): ?><div class="empty-state"><h3>Chưa tìm thấy chỗ ở phù hợp</h3><p>Hãy thử đổi địa điểm, ngày hoặc số khách.</p><a class="btn btn-primary" href="<?= e(url('/')) ?>">Xóa bộ lọc</a></div><?php else: ?><div class="row"><?php foreach($listings as $listing): ?><div class="col-md-6 col-lg-4 mb-4"><article class="listing-card"><a href="<?= e(url('/listings/'.$listing['id'])) ?>" class="card-image-wrap"><img class="card-image" src="<?= e($listing['image_url']?:asset('images/placeholder.svg')) ?>" alt="<?= e($listing['title']) ?>" loading="lazy"></a><?php if(\Core\Auth::check()): ?><button class="favorite-button <?= in_array((int)$listing['id'],$favorites,true)?'is-saved':'' ?>" data-favorite="<?= (int)$listing['id'] ?>" aria-label="Lưu <?= e($listing['title']) ?>">♡</button><?php endif; ?><div class="card-body"><div class="d-flex justify-content-between"><h3><a href="<?= e(url('/listings/'.$listing['id'])) ?>"><?= e($listing['title']) ?></a></h3><span class="rating">★ <?= number_format((float)$listing['rating'],1) ?></span></div><p class="card-meta"><?= e($listing['city']) ?> · <?= e($listing['property_type']) ?> · <?= (int)$listing['max_guests'] ?> khách</p><p class="price"><?= number_format((float)$listing['nightly_price'],0,',','.') ?>đ <span>/ đêm</span></p></div></article></div><?php endforeach; ?></div><?php endif; ?></div></section>

